def as_num(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, int) or isinstance(v, float):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if re.match(r"^-?\d+(\.\d+)?$", s):
            return float(s)
    return None

order = input.get("order") or {}
customer = order.get("customer") or {}
raw_lines = order.get("lines") or []
problems = []

name = str(customer.get("name") or "").strip()
email = str(customer.get("email") or "").strip().lower()
if not name:
    problems.append("customer.name is empty")
if "@" not in email:
    problems.append("customer.email is not an address")

lines = []
total = 0.0
for i, ln in enumerate(raw_lines):
    if not isinstance(ln, dict):
        problems.append("lines[" + str(i) + "] is not an object")
        continue
    label = str(ln.get("name") or "").strip()
    if not label and not ln.get("product_id"):
        problems.append("lines[" + str(i) + "] has no name and no product_id")
        continue
    qty = as_num(ln.get("quantity", 1))
    price = as_num(ln.get("price_unit", 0))
    if qty is None or price is None:
        problems.append("lines[" + str(i) + "] has a non-numeric quantity or price")
        continue
    if qty <= 0 or price < 0:
        problems.append("lines[" + str(i) + "] has a non-positive quantity or negative price")
        continue
    entry = {"name": label, "quantity": qty, "price_unit": price}
    if ln.get("product_id"):
        entry["product_id"] = ln["product_id"]
    lines.append(entry)
    total = total + qty * price

if not lines:
    problems.append("no usable order lines")

ceiling = as_num(input.get("ceiling"))
if ceiling is None:
    ceiling = 0.0
if ceiling > 0 and total > ceiling:
    problems.append("order total " + str(round(total, 2)) + " exceeds max_order_total " + str(ceiling))

output = {
    "ok": not problems,
    "problems": problems,
    "email": email,
    "customer": {
        "name": name,
        "email": email,
        "phone": str(customer.get("phone") or "").strip(),
        "country_code": str(customer.get("country_code") or "").strip(),
        "vat": str(customer.get("vat") or "").strip(),
        "is_company": bool(customer.get("is_company")),
    },
    "lines": lines,
    "subtotal_estimate": round(total, 2),
    "client_order_ref": str(order.get("client_order_ref") or "").strip(),
    "prepaid": str(order.get("payment_terms") or "").strip().lower() == "prepaid",
}

def as_int(v):
