    if isinstance(v, int):
        return v
    if isinstance(v, float):
        return int(v)
    if isinstance(v, str):
        s = v.strip()
        if re.match(r"^\d+$", s):
            return int(s)
    return 0

lookup = input.get("lookup") or {}
norm = input.get("normalized") or {}

upstream_ok = bool(norm.get("ok"))
problems = list(norm.get("problems") or [])

existing_id = 0
if lookup.get("found"):
    existing_id = as_int(lookup.get("partner_id"))

create_vals = {}
to_create = []
if upstream_ok and not existing_id:
