    "problems": problems,
    "existing_partner_id": existing_id,
    "needs_create": bool(upstream_ok and not existing_id),
    "create_vals": create_vals,
    "to_create": to_create,
    "branch": "reuse_existing" if existing_id else "create_new",
    "matched_on": lookup.get("searched_on", "email"),
    "candidates_seen": lookup.get("count", 0),
}

def as_int(v):
    if isinstance(v, bool):
        return 0
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        return int(v)
    if isinstance(v, str):
        s = v.strip()
        if re.match(r"^\d+$", s):
            return int(s)
    return 0

routed = input.get("routed") or {}
created = input.get("created")
norm = input.get("normalized") or {}

partner_id = as_int(routed.get("existing_partner_id"))
source = "lookup"
if not partner_id:
    rows = created if isinstance(created, list) else ([created] if created else [])
    for row in rows:
        if isinstance(row, dict) and row.get("partner_id"):
            partner_id = as_int(row.get("partner_id"))
            source = "created"
            break

problems = list(routed.get("problems") or [])
if not partner_id:
    problems.append("no partner_id available - the lookup missed and creation returned nothing")

output = {
    "ok": bool(routed.get("ok")) and partner_id > 0,
    "problems": problems,
    "partner_id": partner_id,
    "partner_source": source,
    "lines": norm.get("lines") or [],
    "client_order_ref": norm.get("client_order_ref", ""),
    "prepaid": bool(norm.get("prepaid")),
}

def as_num(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, int) or isinstance(v, float):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if re.match(r"^-?\d+(\.\d+)?$", s):
            return float(s)
    return None

posted = input.get("posted") or {}
resolved = input.get("resolved") or {}

enabled = str(input.get("settle_enabled")).strip().lower() in ("1", "true", "yes")
prepaid = bool(resolved.get("prepaid"))

residual = as_num(posted.get("amount_residual"))
if residual is None:
    residual = 0.0

invoice_id = posted.get("invoice_id") or 0

to_settle = []
settle_vals = {}
if not enabled:
    reason = "settle_when_prepaid is off for this station"
elif not prepaid:
    reason = "order payment_terms is not prepaid - leaving the invoice open"
elif residual <= 0:
    reason = "invoice has nothing left to pay"
elif not invoice_id:
    reason = "no invoice_id came back from the post step"
else:
    entry = {
        "invoice_id": invoice_id,
        "amount": residual,
        "memo": "Prepayment for " + str(posted.get("invoice_name") or invoice_id),
    }
    jid = as_num(input.get("journal_id"))
    if jid is not None and jid > 0:
        entry["journal_id"] = int(jid)
    to_settle.append(entry)
    settle_vals = entry
    reason = "prepaid order - settling the full residual"

output = {
    "to_settle": to_settle,
    "settle_vals": settle_vals,
    "will_settle": bool(to_settle),
    "reason": reason,
    "residual": residual,
}

norm = input.get("normalized") or {}
routed = input.get("routed") or {}
order = input.get("order") or {}
invoice = input.get("invoice") or {}
decision = input.get("decision") or {}
payment = input.get("payment")

rows = payment if isinstance(payment, list) else ([payment] if payment else [])
paid_row = rows[0] if rows and isinstance(rows[0], dict) else {}

settled = bool(paid_row)
residual = paid_row.get("amount_residual", invoice.get("amount_residual", 0))

